    titulo = "Norte de Durotar y Orgrimmar", min = 9, max = 12,
    entrenar = "Al 10: Nova de Escarcha (lo más importante: congela a los que te rodean), Armadura de Escarcha (rango 2) e Invocar agua (rango 2). En Orgrimmar tus instructores están en el Valle de los Espíritus: Pephredo.",
    equipo = "En Orgrimmar, en la Hendidura de las Sombras, hay vendedores de telas y varitas. Busca una varita en la subasta.",
    profesion = "En Orgrimmar enseñan Sastrería Snang y Encantamiento Jhag; los materiales de encantamiento los vende Kithas. Activa el vuelo con Doras en la torre del Valle de la Fuerza.",
    pasos = {
      { t = "Desde Cerrotajo sube al norte por el camino. En la Hondonada Ventoseco, Rezlak te da [Las arpías Viento Seco]: recoge los sacos de suministros de las arpías y entrégala; acepta [Asegurar las rutas].", wp = { { m = 1411, z = "Durotar", x = 46.4, y = 22.9, n = "Recoger: Las arpías Viento Seco (Rezlak)", q = 834, a = "A" }, { m = 1411, z = "Durotar", x = 49.2, y = 29.7, n = "Objetivo: Las arpías Viento Seco", q = 834, a = "C" }, { m = 1411, z = "Durotar", x = 46.4, y = 22.9, n = "Entregar: Las arpías Viento Seco (Rezlak)", q = 834, a = "T" }, { m = 1411, z = "Durotar", x = 46.4, y = 22.9, n = "Recoger: Asegurar las rutas (Rezlak)", q = 835, a = "A" } } },
      { t = "Mata salvajes y brujas de la tormenta Viento Seco en la hondonada para [Asegurar las rutas]; la bruja Fizzle Tormenta Oscura, en la Cresta del Trueno al oeste, suelta la garra de [Oscuras tormentas]. Entrega [Asegurar las rutas].", wp = { { m = 1411, z = "Durotar", x = 52.6, y = 22.8, n = "Objetivo: Asegurar las rutas", q = 835, a = "C" }, { m = 1411, z = "Durotar", x = 42.1, y = 26.7, n = "Objetivo: Oscuras tormentas", q = 806, a = "C" }, { m = 1411, z = "Durotar", x = 46.4, y = 22.9, n = "Entregar: Asegurar las rutas (Rezlak)", q = 835, a = "T" } } },
      { t = "Junto al río del oeste, Misha Tor'kren te da [Perdido, pero no olvidado]: los cocodrilos Fauceterror sueltan el amuleto de Kron.", wp = { { m = 1411, z = "Durotar", x = 43.1, y = 30.2, n = "Recoger: Perdido, pero no olvidado (Misha Tor'kren)", q = 816, a = "A" }, { m = 1411, z = "Durotar", x = 35.7, y = 25.5, n = "Objetivo: Perdido, pero no olvidado", q = 816, a = "C" }, { m = 1411, z = "Durotar", x = 43.1, y = 30.2, n = "Entregar: Perdido, pero no olvidado (Misha Tor'kren)", q = 816, a = "T" } } },
      { t = "Vuelve a Cerrotajo: entrega [Oscuras tormentas] a Orgnil Escaralma y acepta [Margoz].", wp = { { m = 1411, z = "Durotar", x = 52.2, y = 43.1, n = "Entregar: Oscuras tormentas (Orgnil Escaralma)", q = 806, a = "T" }, { m = 1411, z = "Durotar", x = 52.2, y = 43.1, n = "Recoger: Margoz (Orgnil Escaralma)", q = 828, a = "A" } } },
      { t = "Takrin Abrecaminos, en Cerrotajo, te da [Nuevo recluta de la Horda]: se entrega en Los Baldíos, en el Puesto del Vigía Lejano.", wp = { { m = 1411, z = "Durotar", x = 50.8, y = 43.6, n = "Recoger: Nuevo recluta de la Horda (Takrin Abrecaminos)", q = 840, a = "A" } } },
      { t = "Sigue al norte hasta Orgrimmar y entra por la puerta del sur. Activa el vuelo con Doras en la torre del Valle de la Fuerza. En Grommash Hold, Thrall te da [Enemigos ocultos]. Si tienes las órdenes del almirante, entrega [Las órdenes del almirante] a Nazgrel.", wp = { { m = 1454, z = "Orgrimmar", x = 45.1, y = 63.9, n = "Doras", npc = 3310 }, { m = 1454, z = "Orgrimmar", x = 31.7, y = 37.8, n = "Recoger: Enemigos ocultos (Thrall)", q = 5726, a = "A" } }, comprobar = { vuelo = "Orgrimmar" } },
      { t = "Nivel 10: en el Valle de los Espíritus (al oeste de Orgrimmar) entrena con Pephredo: Nova de Escarcha, Armadura de Escarcha (rango 2) e Invocar agua (rango 2). Aprende también Sastrería con Snang, en la Hendidura de las Sombras, si no la tienes. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 38.4, y = 85.6, n = "Pephredo", npc = 5882 }, { m = 1454, z = "Orgrimmar", x = 62.9, y = 49.2, n = "Snang", npc = 2855 } }, comprobar = { hechizos = { 122 } } },
      { t = "Sal de Orgrimmar por la puerta del sur. Junto a la Roca del Cráneo (al este de la puerta), entrega [Margoz] a Margoz y acepta [Roca del Cráneo]: dentro de la cueva mata cultores del Filo Ardiente por los collares y las insignias de teniente de [Enemigos ocultos]. Si te cae el pergamino de [Sombras Ardientes], léelo.", wp = { { m = 1411, z = "Durotar", x = 56.4, y = 20.0, n = "Entregar: Margoz (Margoz)", q = 828, a = "T" }, { m = 1411, z = "Durotar", x = 56.4, y = 20.0, n = "Recoger: Roca del Cráneo (Margoz)", q = 827, a = "A" }, { m = 1411, z = "Durotar", x = 52.9, y = 9.3, n = "Objetivo: Roca del Cráneo", q = 827, a = "C" }, { m = 1411, z = "Durotar", x = 52.9, y = 9.3, n = "Objetivo: Enemigos ocultos", q = 5726, a = "C" } } },
      { t = "Entrega [Roca del Cráneo] a Margoz y acepta [Neeru Hojafuego]. Vuelve a Orgrimmar: en la Hendidura de las Sombras Neeru Hojafuego recibe [Neeru Hojafuego] (y [Sombras Ardientes]) y te da [Ak'Zeloth]; Thrall recibe [Enemigos ocultos] en Grommash Hold.", wp = { { m = 1411, z = "Durotar", x = 56.4, y = 20.0, n = "Entregar: Roca del Cráneo (Margoz)", q = 827, a = "T" }, { m = 1411, z = "Durotar", x = 56.4, y = 20.0, n = "Recoger: Neeru Hojafuego (Margoz)", q = 829, a = "A" }, { m = 1454, z = "Orgrimmar", x = 49.5, y = 50.6, n = "Entregar: Neeru Hojafuego (Neeru Hojafuego)", q = 829, a = "T" }, { m = 1454, z = "Orgrimmar", x = 49.5, y = 50.6, n = "Recoger: Ak'Zeloth (Neeru Hojafuego)", q = 809, a = "A" }, { m = 1454, z = "Orgrimmar", x = 31.7, y = 37.8, n = "Entregar: Enemigos ocultos (Thrall)", q = 5726, a = "T" } } },

      { t = "Misión extra en otra zona de tu nivel (Mulgore): [Los hábitos del cazador] (nivel 10). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1412, z = "Mulgore", x = 46, y = 63.4, n = "Recoger: Los hábitos del cazador (Skorn Nubeblanca)", q = 861, a = "A" }, { m = 1412, z = "Mulgore", x = 50.7, y = 31.7, n = "Objetivo: Los hábitos del cazador", q = 861, a = "C" }, { m = 1456, z = "Cima del Trueno", x = 61.5, y = 80.9, n = "Entregar: Los hábitos del cazador (Melor Pezuñapétrea)", q = 861, a = "T" } } }, -- REFUERZO_97 q=861
