  {
    titulo = "Los Baldíos: el Vigía Lejano y El Cruce", min = 10, max = 14,
    entrenar = "Primer talento al 10: Escarcha > Descarga de Escarcha mejorada (5 puntos, del 10 al 14). En Los Baldíos no hay instructor de mago: vuelve a Orgrimmar (Pephredo) cada dos niveles. Al 12: Invocar comida (rango 2) y Bola de Fuego (rango 3).",
    equipo = "Las misiones de El Cruce dan piezas de tela.",
    profesion = "Kil'hala, en El Cruce, enseña Sastrería hasta oficial y Wrahk, al lado, vende el hilo. Pon la piedra de hogar en El Cruce.",
    pasos = {
      { t = "Sal de Orgrimmar por la puerta del oeste y cruza el puente del río al Puesto del Vigía Lejano. Entrega [Nuevo recluta de la Horda] a Kargal Marca de Guerra y acepta [Servicio militar en El Cruce]. Entrega también [Ak'Zeloth] a Ak'Zeloth y acepta [La Semilla del Demonio]. Recoge una piedra de poder imperfecta de su mesa. Dura 30 minutos.", wp = { { m = 1413, z = "Los Baldíos", x = 62.3, y = 19.4, n = "Entregar: Nuevo recluta de la Horda (Kargal Marca de Guerra)", q = 840, a = "T" }, { m = 1413, z = "Los Baldíos", x = 62.3, y = 19.4, n = "Recoger: Servicio militar en El Cruce (Kargal Marca de Guerra)", q = 842, a = "A" }, { m = 1413, z = "Los Baldíos", x = 62.3, y = 20.1, n = "Entregar: Ak'Zeloth (Ak'Zeloth)", q = 809, a = "T" }, { m = 1413, z = "Los Baldíos", x = 62.3, y = 20.1, n = "Recoger: La Semilla del Demonio (Ak'Zeloth)", q = 924, a = "A" } } },
      { t = "Sigue el camino al sur hasta El Cruce. Entrega [Servicio militar en El Cruce] a Sergra Espinoscura y acepta [La amenaza de los zancudos de llanura]. Acepta también [Acabar con los ataques de los Crines de Acero] y [Suministros para El Cruce] (Thork), [Los raptores ladrones] (Gazrog), [Esporas de hongos] (Boticario Helbrim) y [Las Charcas del Olvido] (Tonga Tótem de Runa). Pon la piedra de hogar con Tabernero Boorand Ventollano y activa el vuelo con Devrak.", wp = { { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: Servicio militar en El Cruce (Sergra Espinoscura)", q = 842, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: La amenaza de los zancudos de llanura (Sergra Espinoscura)", q = 844, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: Acabar con los ataques de los Crines de Acero (Thork)", q = 871, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: Suministros para El Cruce (Thork)", q = 5041, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.9, y = 30.3, n = "Recoger: Los raptores ladrones (Gazrog)", q = 869, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.4, y = 30.1, n = "Recoger: Esporas de hongos (Boticario Helbrim)", q = 848, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Recoger: Las Charcas del Olvido (Tonga Tótem de Runa)", q = 870, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 29.9, n = "Tabernero Boorand Ventollano", npc = 3934 }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.3, n = "Devrak", npc = 3615 } }, comprobar = { vuelo = "El Cruce" } },
      { t = "En El Cruce aprende Sastrería con Kil'hala y compra hilo a Wrahk, al lado.", wp = { { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.7, n = "Kil'hala", npc = 3484 }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.7, n = "Wrahk", npc = 3485 } }, comprobar = { oficios = { 197 } } },
      { t = "Por el mismo camino, en los campamentos de los Crines de Acero del nordeste: mata buscaquas, tejespinas y cazadores para [Acabar con los ataques de los Crines de Acero] y recoge los cajones de suministros para [Suministros para El Cruce]. Mata zancudos de llanura para [La amenaza de los zancudos de llanura] por el camino.", wp = { { m = 1413, z = "Los Baldíos", x = 55.3, y = 25.8, n = "Objetivo: Acabar con los ataques de los Crines de Acero", q = 871, a = "C" }, { m = 1413, z = "Los Baldíos", x = 59.0, y = 25.8, n = "Objetivo: Suministros para El Cruce", q = 5041, a = "C" }, { m = 1413, z = "Los Baldíos", x = 53.1, y = 31.3, n = "Objetivo: La amenaza de los zancudos de llanura", q = 844, a = "C" } } },
      { t = "Vuelve a El Cruce: entrega [Acabar con los ataques de los Crines de Acero], [Suministros para El Cruce] y [La amenaza de los zancudos de llanura]. Acepta [El fin de las hostilidades] y [El astacebra].", wp = { { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: Acabar con los ataques de los Crines de Acero (Thork)", q = 871, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: Suministros para El Cruce (Thork)", q = 5041, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: La amenaza de los zancudos de llanura (Sergra Espinoscura)", q = 844, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: El fin de las hostilidades (Thork)", q = 872, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: El astacebra (Sergra Espinoscura)", q = 845, a = "A" } } },
      { t = "Al noroeste, en las Charcas del Olvido, explora el agua para [Las Charcas del Olvido] y recoge los champiñones de [Esporas de hongos]. Para [La Semilla del Demonio], sube por la ladera norte del pico Brumafunesta y usa en el Altar de Fuego la piedra que recogiste. Si caducó, vuelve a la mesa de Ak'Zeloth por otra. Mata astacebras para [El astacebra].", wp = { { m = 1413, z = "Los Baldíos", x = 45.1, y = 22.5, n = "Objetivo: Las Charcas del Olvido", q = 870, a = "C" }, { m = 1413, z = "Los Baldíos", x = 46.6, y = 39.4, n = "Objetivo: Esporas de hongos", q = 848, a = "C" }, { m = 1413, z = "Los Baldíos", x = 48.0, y = 19.1, n = "Objetivo: La Semilla del Demonio", q = 924, a = "C" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 36.4, n = "Objetivo: El astacebra", q = 845, a = "C" } } },
      { t = "De vuelta, mata al jefe Kreenig Gruñucico y a geománticos y defensores Crines de Acero, al este del camino, para [El fin de las hostilidades]. Sube luego al Puesto del Vigía Lejano y entrega [La Semilla del Demonio] a Ak'Zeloth.", wp = { { m = 1413, z = "Los Baldíos", x = 58.3, y = 25.2, n = "Objetivo: El fin de las hostilidades", q = 872, a = "C" }, { m = 1413, z = "Los Baldíos", x = 62.3, y = 20.1, n = "Entregar: La Semilla del Demonio (Ak'Zeloth)", q = 924, a = "T" } } },
      { t = "En El Cruce entrega [El fin de las hostilidades], [El astacebra], [Las Charcas del Olvido] y [Esporas de hongos]. Acepta [Merodeadores de los Baldíos] y [El Oasis Estancado].", wp = { { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: El fin de las hostilidades (Thork)", q = 872, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: El astacebra (Sergra Espinoscura)", q = 845, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Entregar: Las Charcas del Olvido (Tonga Tótem de Runa)", q = 870, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.4, y = 30.1, n = "Entregar: Esporas de hongos (Boticario Helbrim)", q = 848, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: Merodeadores de los Baldíos (Sergra Espinoscura)", q = 903, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Recoger: El Oasis Estancado (Tonga Tótem de Runa)", q = 877, a = "A" } } },
      { t = "Misión extra para no quedarte corto de nivel: [SE BUSCA: Barón Longavera] (nivel 16). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1413, z = "Los Baldíos", x = 62.6, y = 37.5, n = "Recoger: SE BUSCA: Barón Longavera (SE BUSCA)", q = 895, a = "A" }, { m = 1413, z = "Los Baldíos", x = 63.4, y = 48.6, n = "Objetivo: SE BUSCA: Barón Longavera", q = 895, a = "C" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Entregar: SE BUSCA: Barón Longavera (Gazlowe)", q = 895, a = "T" } } }, -- REFUERZO_97 q=895
      { t = "Misión extra para no quedarte corto de nivel: [Pellejo de los descarriados] (nivel 17). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1413, z = "Los Baldíos", x = 46, y = 35.7, n = "Recoger: Pellejo de los descarriados (Nalpak)", q = 1486, a = "A" }, { m = 1413, z = "Los Baldíos", x = 46, y = 35.7, n = "Entregar: Pellejo de los descarriados (Nalpak)", q = 1486, a = "T" } } }, -- REFUERZO_97 q=1486
      { t = "Nivel 12: vuela a Orgrimmar (o usa Teletransporte: Orgrimmar) y entrena con Pephredo, en el Valle de los Espíritus: Invocar comida (rango 2), Bola de Fuego (rango 3) y Caída lenta. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 38.4, y = 85.6, n = "Pephredo", npc = 5882 } }, comprobar = { hechizos = { 597 } } },

