    pasos = {
      { t = "En El Cruce acepta [Los brazales de centauro] y [Los jefes de Kolkar] a Regthar Portamorta (al noroeste, en el puesto de Regthar), [Arpías saqueadoras] (Darsok Movedaga) y [Consumido por el odio] y [Perdida en la batalla] (Mankrik).", wp = { { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Recoger: Los brazales de centauro (Regthar Portamorta)", q = 855, a = "A" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Recoger: Los jefes de Kolkar (Regthar Portamorta)", q = 850, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.6, y = 30.9, n = "Recoger: Arpías saqueadoras (Darsok Movedaga)", q = 867, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 31.6, n = "Recoger: Consumido por el odio (Mankrik)", q = 899, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 31.6, n = "Recoger: Perdida en la batalla (Mankrik)", q = 4921, a = "A" } } },
