  {
    titulo = "Vallefresno", min = 24, max = 27,
    entrenar = "Al 26: Cono de frío, Nova de Escarcha (rango 2) y Descarga de Escarcha (rango 5). Talentos: 24-25 Nova de Escarcha mejorada y 26-28 Hacer añicos (Shatter).",
    equipo = "[Avanzada de Vallefresno] y [Suministros Grito de Guerra] dan piezas de tela. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "El paño de lana cae de los humanoides de Vallefresno: guárdalo para Sastrería y para las vendas.",
    pasos = {
      { t = "De El Cruce sube al norte por el camino hasta Vallefresno (por el Paso del Hachazo). En el Puesto del Hachazo activa el vuelo con Vhulgra y pon la piedra de hogar con Tabernero Kaylisk. Acepta [Avanzada de Vallefresno] (Kuray'bin), [Los cuernos de sátiro] (Pixie)y [Suministros Grito de Guerra] (Locke Okarr).", wp = { { m = 1440, z = "Vallefresno", x = 73.2, y = 61.6, n = "Vhulgra", npc = 12616 }, { m = 1440, z = "Vallefresno", x = 74.0, y = 60.6, n = "Tabernero Kaylisk", npc = 12196 }, { m = 1440, z = "Vallefresno", x = 71.1, y = 68.1, n = "Recoger: Avanzada de Vallefresno (Kuray'bin)", q = 6503, a = "A" }, { m = 1440, z = "Vallefresno", x = 73.1, y = 61.5, n = "Recoger: Los cuernos de sátiro (Pixie)", q = 6441, a = "A" }, { m = 1440, z = "Vallefresno", x = 71.4, y = 67.6, n = "Recoger: Suministros Grito de Guerra (Locke Okarr)", q = 6571, a = "A" } }, comprobar = { vuelo = "Hachazo" } },
      { t = "Al sur del puesto mata avanzados de Vallefresno para [Avanzada de Vallefresno]. Por el camino, junta cuerda de los sátiros y del Bosque Mortecino para [Suministros Grito de Guerra].", wp = { { m = 1440, z = "Vallefresno", x = 73.5, y = 72.3, n = "Objetivo: Avanzada de Vallefresno", q = 6503, a = "C" }, { m = 1440, z = "Vallefresno", x = 53.1, y = 62.1, n = "Objetivo: Suministros Grito de Guerra", q = 6571, a = "C" } } },
      { t = "Al este, en el Bosque de la Muerte: sátiros Corrupto por los cuernos de [Los cuernos de sátiro]. Si encuentras a Shadumbra, Ursangous o Garrafilada (raros de la Caza de Senani Truenozón), sus objetos empiezan misiones de recompensa.", wp = { { m = 1440, z = "Vallefresno", x = 79.8, y = 47.7, n = "Objetivo: Los cuernos de sátiro", q = 6441, a = "C" } } },
      { t = "Entrega en el Puesto del Hachazo [Avanzada de Vallefresno], [Los cuernos de sátiro] y [Suministros Grito de Guerra].", wp = { { m = 1440, z = "Vallefresno", x = 71.1, y = 68.1, n = "Entregar: Avanzada de Vallefresno (Kuray'bin)", q = 6503, a = "T" }, { m = 1440, z = "Vallefresno", x = 73.1, y = 61.5, n = "Entregar: Los cuernos de sátiro (Pixie)", q = 6441, a = "T" }, { m = 1440, z = "Vallefresno", x = 71.4, y = 67.6, n = "Entregar: Suministros Grito de Guerra (Locke Okarr)", q = 6571, a = "T" } } },
