  {
    titulo = "Las Mil Agujas", min = 26, max = 30,
    entrenar = "Al 28: Gema de maná e Intelecto Arcano (rango 3). Al 30: Armadura de hielo (sustituye a Armadura de Escarcha) y Teletransporte: Cima del Trueno. Talentos: 29 Canalización de Escarcha y 30-31 Dedos de Escarcha (Fingers of Frost).",
    equipo = "Las misiones del Poblado Viento Libre dan anillos y piezas de tela. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Los Galak y los Tótem Siniestro sueltan paño de lana y de seda.",
    pasos = {
      { t = "Antes de llegar al Poblado Viento Libre, detente en el Gran Elevador y recoge [Mensaje para el Poblado Viento Libre] de Valiente Cuerno de Luna. Después ve al poblado y entrégalo a Vigiarrisco Cuernolargo para abrir [Apaciguar al centauro].", wp = { { m = 1441, z = "Las Mil Agujas", x = 32.2, y = 22.1, n = "Recoger: Mensaje para el Poblado Viento Libre (Valiente Cuerno de Luna)", q = 4542, a = "A", npc = 10079 } } },
      { t = "De Taurajo baja al sur por el camino hasta Las Mil Agujas. En el Poblado Viento Libre activa el vuelo con Nyse, pon la piedra de hogar con Tabernero Abeqwa y acepta [Apaciguar al centauro] (Vigiarrisco Cuernolargo), [Un huevo extraño] (Hagar Relampafauce), [Jinete del viento] (Elu).", wp = { { m = 1441, z = "Las Mil Agujas", x = 45.1, y = 49.1, n = "Nyse", npc = 4317 }, { m = 1441, z = "Las Mil Agujas", x = 46.1, y = 51.5, n = "Tabernero Abeqwa", npc = 11116 }, { m = 1441, z = "Las Mil Agujas", x = 45.7, y = 50.7, n = "Entregar: Mensaje para el Poblado Viento Libre (Vigiarrisco Cuernolargo)", q = 4542, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 45.7, y = 50.7, n = "Recoger: Apaciguar al centauro (Vigiarrisco Cuernolargo)", q = 4841, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 44.6, y = 50.3, n = "Recoger: Un huevo extraño (Hagar Relampafauce)", q = 4821, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 44.9, y = 48.9, n = "Recoger: Jinete del viento (Elu)", q = 4767, a = "A" } }, comprobar = { vuelo = "Viento Libre" } },
      { t = "Al norte del poblado, en los campamentos Galak, mata exploradores, retadores y cazavientos Galak para [Apaciguar al centauro]. En las rocas altas del oeste recoge el huevo extraño de [Un huevo extraño] y los huevos de dracoleón Nido Alto de los nidos para [Jinete del viento].", wp = { { m = 1441, z = "Las Mil Agujas", x = 43.8, y = 39.2, n = "Objetivo: Apaciguar al centauro", q = 4841, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 37.6, y = 56.1, n = "Objetivo: Un huevo extraño", q = 4821, a = "C" }, { m = 1441, z = "Las Mil Agujas", x = 12.3, y = 36.1, n = "Objetivo: Jinete del viento", q = 4767, a = "C" } } },
      { t = "Entrega en Viento Libre [Apaciguar al centauro], [Un huevo extraño] y [Jinete del viento]. Acepta [Espiando a los Tótem Siniestro] y [Venganza].", wp = { { m = 1441, z = "Las Mil Agujas", x = 45.7, y = 50.7, n = "Entregar: Apaciguar al centauro (Vigiarrisco Cuernolargo)", q = 4841, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 44.6, y = 50.3, n = "Entregar: Un huevo extraño (Hagar Relampafauce)", q = 4821, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 44.9, y = 48.9, n = "Entregar: Jinete del viento (Elu)", q = 4767, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 45.7, y = 50.7, n = "Recoger: Espiando a los Tótem Siniestro (Vigiarrisco Cuernolargo)", q = 5064, a = "A" }, { m = 1441, z = "Las Mil Agujas", x = 44.6, y = 50.3, n = "Recoger: Venganza (Hagar Relampafauce)", q = 4865, a = "A" } } },
      { t = "Al noroeste, en el Pináculo Nube Negra de los Tótem Siniestro, busca las tres notas secretas para [Espiando a los Tótem Siniestro].", wp = { { m = 1441, z = "Las Mil Agujas", x = 36.5, y = 40.8, n = "Objetivo: Espiando a los Tótem Siniestro", q = 5064, a = "C" } } },
      { t = "Entrega [Espiando a los Tótem Siniestro] en Viento Libre. Lleva [Venganza] a Motega Pirocabello, en el Campamento de la Piedra Cortada, al oeste.", wp = { { m = 1441, z = "Las Mil Agujas", x = 45.7, y = 50.7, n = "Entregar: Espiando a los Tótem Siniestro (Vigiarrisco Cuernolargo)", q = 5064, a = "T" }, { m = 1441, z = "Las Mil Agujas", x = 21.5, y = 32.4, n = "Entregar: Venganza (Motega Pirocabello)", q = 4865, a = "T" } } },
