    pasos = {
      { t = "Nivel 30: vuela a Orgrimmar (o usa Teletransporte: Orgrimmar) y entrena con Pephredo, en el Valle de los Espíritus: Armadura de hielo, Teletransporte: Cima del Trueno y los rangos nuevos. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 38.4, y = 85.6, n = "Pephredo", npc = 5882 } }, comprobar = { hechizos = { 7302 } } },
      { t = "Vuela a Viento Libre y sigue al este por Las Mil Agujas hasta El Desierto de Sal.", wp = { { m = 1441, z = "Las Mil Agujas", x = 78.0, y = 77.0, n = "El Desierto de Sal" } }, comprobar = { llegar = 1441 } },
