      { t = "Encargo opcional de Desolace: [El khan Hratha]. Si Umarak te lo ofrece a partir del nivel 35, reúne un grupo. Consigue la boquilla de un centauro Maraudine, úsala en el cuerno de la cima del Valle de las Lanzas y entrega a Umarak el fragmento de llave.", wp = { { m = 1443, z = "Desolace", x = 43.5, y = 79.0, n = "Recoger: El khan Hratha (Umarak)", q = 96222, a = "A" }, { m = 1443, z = "Desolace", x = 29.6, y = 52.0, n = "Objetivo: El khan Hratha", q = 96222, a = "C" }, { m = 1443, z = "Desolace", x = 43.5, y = 79.0, n = "Entregar: El khan Hratha (Umarak)", q = 96222, a = "T" } } }, -- Paso conservado 1380
      { t = "Si ya entregaste [El khan Hratha] a Umarak o decidiste saltarlo, continúa con el recorrido de Desolace." }, -- Paso conservado 1381
      { t = "Nivel 38: vuela a Orgrimmar (o usa Teletransporte: Orgrimmar) y entrena con Pephredo, en el Valle de los Espíritus: Descarga de Escarcha (rango 7) y Explosión de Fuego (rango 5). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 38.4, y = 85.6, n = "Pephredo", npc = 5882 } }, comprobar = { hechizos = { 8408 } } },
