    entrenar = "Al 44: Descarga de Escarcha (rango 8) y Lanza de hielo (rango 4). En el Rocal no hay instructor de mago: usa Teletransporte: Orgrimmar y vuelve con la piedra de hogar. Talentos 42-44: Resiliencia arcana.",
    equipo = "Con grupo: Uldaman (41-50) en las Tierras Inhóspitas, desde Kargath. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "El tejido mágico cae de los humanoides de las Tierras Inhóspitas y del Pantano de las Penas.",
    pasos = {
      { t = "Vuela a Sentencia (Arathi) y ve a pie al sur: cruza el Paso de Thandol, Los Humedales y el Loch Modan (tierras de la Alianza: ve con cuidado) y entra por el sur del Loch Modan en las Tierras Inhóspitas. En Kargath, al oeste, activa el vuelo con Gorrik, pon la piedra de hogar con Tabernero Shul'kar y acepta [Componentes de Tierras Inhóspitas] (Jarkal Musgofusión), [Ladrones coyote] (Neeka Marca de Sangre), [Alas de águila ratonera a la parrilla] (Aparejez) y [Alianzas rotas] (Gorn).", wp = { { m = 1418, z = "Tierras Inhóspitas", x = 4.0, y = 44.8, n = "Gorrik", npc = 2861 }, { m = 1418, z = "Tierras Inhóspitas", x = 2.8, y = 45.9, n = "Tabernero Shul'kar", npc = 9356 }, { m = 1418, z = "Tierras Inhóspitas", x = 2.4, y = 46.1, n = "Recoger: Componentes de Tierras Inhóspitas (Jarkal Musgofusión)", q = 2258, a = "A" }, { m = 1418, z = "Tierras Inhóspitas", x = 6.5, y = 47.2, n = "Recoger: Ladrones coyote (Neeka Marca de Sangre)", q = 1419, a = "A" }, { m = 1418, z = "Tierras Inhóspitas", x = 42.4, y = 52.9, n = "Recoger: Alas de águila ratonera a la parrilla (Aparejez)", q = 703, a = "A" }, { m = 1418, z = "Tierras Inhóspitas", x = 2.9, y = 45.6, n = "Recoger: Alianzas rotas (Gorn)", q = 782, a = "A" } }, comprobar = { vuelo = "Kargath" } },
      { t = "Por las Tierras Inhóspitas: coyotes para [Ladrones coyote], ratoneras para [Alas de águila ratonera a la parrilla], los componentes de [Componentes de Tierras Inhóspitas] y los ogros de [Alianzas rotas].", wp = { { m = 1418, z = "Tierras Inhóspitas", x = 31.4, y = 62.4, n = "Objetivo: Ladrones coyote", q = 1419, a = "C" }, { m = 1418, z = "Tierras Inhóspitas", x = 16.2, y = 60.1, n = "Objetivo: Alas de águila ratonera a la parrilla", q = 703, a = "C" }, { m = 1418, z = "Tierras Inhóspitas", x = 15.4, y = 37.7, n = "Objetivo: Componentes de Tierras Inhóspitas", q = 2258, a = "C" }, { m = 1418, z = "Tierras Inhóspitas", x = 12.6, y = 75.5, n = "Objetivo: Alianzas rotas", q = 782, a = "C" } } },
